// Verifies the HMAC-SHA256 signature sent by Convex.
// Signed message: `${timestamp}.POST.${path}.${rawBody}` (see convex/lib/hmac.ts)
const crypto = require('crypto');
const PATH = '/webhook/lendloop-request-events';
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.LENDLOOP_SHARED_SECRET;
const fail = (reason) => [{ json: { valid: false, reason } }];

if (!secret) return fail('secret not configured');
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'];
if (!ts || !sig) return fail('missing headers');

// Reject old requests (replay protection).
const age = Math.abs(Date.now() / 1000 - Number(ts));
if (!Number.isFinite(age) || age > 300) return fail('stale timestamp');

// Verify against the RAW body, byte for byte.
let raw = '';
try {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  return fail('raw body unavailable');
}
const expected = crypto.createHmac('sha256', secret).update(`${ts}.POST.${PATH}.${raw}`).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(String(sig).toLowerCase());
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return fail('bad signature');

return [{ json: { valid: true, payload: JSON.parse(raw) } }];

// Idempotency: Convex retries failed deliveries with the same eventId.
// Already-processed ids are acknowledged without notifying twice.
const payload = $input.first().json.payload;
const seen = $getWorkflowStaticData('global').seen || [];
return [{ json: { payload, duplicate: seen.includes(payload.eventId) } }];

// Uses ONLY the fields it needs: recipient name + email, tool name, dates.
// Mock notification (logged). Swap this node for Email / Slack / Discord in production.
const p = $input.first().json.payload;
const { loan, recipient } = p;
const messages = {
  created: `${recipient.name}, someone asked to borrow your "${loan.toolName}" (${loan.startDate} to ${loan.endDate}). Open LendLoop to approve or decline.`,
  approved: `${recipient.name}, your request for "${loan.toolName}" (${loan.startDate} to ${loan.endDate}) was approved.`,
  declined: `${recipient.name}, your request for "${loan.toolName}" was declined.`,
  returned: `${recipient.name}, "${loan.toolName}" was marked as returned. Thank you!`,
};
const text = messages[p.event];
if (!text) throw new Error('Unknown event: ' + p.event); // visible failure -> error workflow + Convex retry

console.log(`[LendLoop mock notification] to=${recipient.email ?? 'no-email'} :: ${text}`);

// Remember the event only AFTER it was handled successfully.
const data = $getWorkflowStaticData('global');
data.seen = [...(data.seen || []), p.eventId].slice(-500);

return [{ json: { eventId: p.eventId, to: recipient.email, text } }];
